  this.path([[x+.67,y1+.025,roof+10],[x+.83,y1+.025,roof+10],[x+.83,y1+.025,roof+25],[x+.67,y1+.025,roof+25]],'#efcf89','#e9d4b5',1.5);
  this.line([x+.84,y1+.03,z+20],[x+.84,y1+.03,z+23],'#e7bd73',2);
