  this.path([[x-w*1.45,y+w*1.45,z+h+4],[x+w*1.45,y+w*1.45,z+h+4],[x,y,z+h+17]],'#8b6c3f');
  this.path([[x+w*1.45,y-w*1.45,z+h+4],[x+w*1.45,y+w*1.45,z+h+4],[x,y,z+h+17]],'#b8914d');
