  this.box(x+.035,y+.025,x+w-.035,y+d-.025,z,bottom,'#b88e51','#906831','#78542f');
  this.path([[x+.035,y+d-.025,bottom],[x+w-.035,y+d-.025,bottom],[x+w,y+d,top],[x,y+d,top]],'#bc8f51');
  this.path([[x+w-.035,y+.025,bottom],[x+w-.035,y+d-.025,bottom],[x+w,y+d,top],[x+w,y,top]],'#a87d41');
