   for(let j=0;j<24;j++){const a=j*Math.PI/12,r=10+(j%2)*1.3,u=Math.cos(a)*r; crown.push([xx+u/(P.HW*2),yy-u/(P.HW*2),head+Math.sin(a)*r*.82]);}
