  // repeated bubble silhouettes and bare flat turf of the previous garden.
  const colours=['#739052','#8a9e59','#a2ad67','#657f4b','#94a85f'];
  const shades=['#5a7446','#708647','#7e924d','#567047','#728a4a'];
