   const angle=((i*137+seed*47)%360)*Math.PI/180;
   const u=Math.cos(angle)*h*.17,base=z+h*(.16+(i%3)*.12),xx=x+u/(P.HW*2),yy=y-u/(P.HW*2);
   const dx=Math.cos(angle)*h*.48,dz=h*(.22+(i*3%7)*.035),tone=(i+seed)%5;
