    for(let j=0;j<24;j++){const a=j*Math.PI/12,r=radius*(1+(j%2)*.08),v=Math.cos(a)*r;crown.push([xx+v/(P.HW*2),yy-v/(P.HW*2),head+Math.sin(a)*r*.84]);}
