  for(const pair of[[a,c],[c,e],[e,a],[e,d],[d,b],[c,d]])this.line(pair[0],pair[1],'#cda15e',2.3);
  this.line([x,y-.12,z+36],[x,y-.12,z+43],'#64786a',2);
  this.line([x,y-.23,z+44],[x,y+.01,z+44],'#8d7055',3);
  this.line([x,y+.16,z+36],[x,y+.1,z+48],'#64786a',2);
