    if(r.images?.houseFront&&r.ctx){const ctx=r.ctx;ctx.save();ctx.transform(1,-.5,0,1,c.origin.x,c.origin.y);ctx.drawImage(r.images.houseFront,0,0,c.imageWidth,c.imageHeight);ctx.restore();}
