  // beyond the viewport. Their much wider cache must not shrink the game.
  this.bounds={left:-160,right:1580,top:-145,bottom:1110};
  const make=(b,paint,scale=2)=>{
   const canvas=document.createElement('canvas');canvas.width=Math.ceil((b.right-b.left)*scale);canvas.height=Math.ceil((b.bottom-b.top)*scale);
   const c=canvas.getContext('2d');c.setTransform(scale,0,0,scale,-b.left*scale,-b.top*scale);c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';
   paint(new Painter(c,r.images,r.assets));return{canvas,bounds:b};
  };
  // Only the scenery crossing a live actor needs a separate draw. Bake the
  // rest into the base once, instead of blitting two almost-empty hall layers.
  const cubbies={left:818,top:335,right:1228,bottom:632};
  const gallery={left:1158,top:411,right:1238,bottom:483};
  const outside=(p,holes,paint)=>{const c=p.ctx;c.save();for(const b of holes){c.beginPath();c.rect(-2000,-2000,6000,6000);c.rect(b.left,b.top,b.right-b.left,b.bottom-b.top);c.clip('evenodd');}paint(p);c.restore();};
  const middle=p=>{this.cabinetLips(p);this.galleryLower(p);this.counter(p);};
  const front=p=>{this.galleryUpper(p);this.details(p);};
  this.exteriorLayer=ex?make({left:eb.left-4,top:eb.top-4,right:eb.right+4,bottom:eb.bottom+4},p=>{ex.r=p;ex.draw(false);},1.25):null;
  this.layers=[
   make(bounds,p=>{this.foundation(p);this.walls(p);this.stair(p);this.cabinet(p);outside(p,[cubbies],middle);outside(p,[cubbies,gallery],front);}),
   make(cubbies,p=>{middle(p);outside(p,[gallery],front);}),
   make(gallery,front)
  ];
