  p.face('y',5.2,7.2,-5,c=>{c.fillStyle='#b48e5f';c.fillRect(0,0,7.2*P.HW,9);c.strokeStyle='#dec299';c.lineWidth=1.2;for(let i=0;i<7.2*P.HW;i+=12){c.beginPath();c.moveTo(i,0);c.lineTo(i+6,8);c.lineTo(i+12,0);c.stroke();}});
  for(let x=-3;x<7.2;x+=.5)for(let y=-2;y<5.2;y+=.5){const shade=((Math.round(x*2)*7+Math.round(y*2)*13+200)%5)*.012;p.poly([[x,y,.05],[Math.min(x+.5,7.2),y,.05],[Math.min(x+.5,7.2),Math.min(y+.5,5.2),.05],[x,Math.min(y+.5,5.2),.05]],'rgba(170,126,77,'+shade+')','none');}
