  p.line3([-2.99,4.99,313],[-2.99,2.2,428],'#eed5a8',8);p.line3([-2.99,2.2,428],[-2.99,-.69,313],'#eed5a8',8);
  p.face('x',-2.6,-1.965,145,c=>{p.arch(c,0,0,1.5*P.HW,145);c.strokeStyle='#f0d9ae';c.lineWidth=8;c.stroke();p.arch(c,3,4,1.5*P.HW-6,141);c.strokeStyle='#b9a077';c.lineWidth=1;c.stroke();});
  p.box(-2.68,-2.3,1.66,.3,-6,6,'stone');
  p.box(-2.68,-2.05,1.66,.34,0,5,'stone');p.box(-1.13,-1.98,.07,.72,5,108,'teal');
