   p.poly([[xx,front+.02,z],[xx+.08,front-.18,z+6],[xx+.08,front-.18,z+rh-5],[xx,front+.02,z+rh-4]],ginger?'#743d30':'#293d52');
   p.face('x',xx,front+.013,z+rh-4,c=>{const g=c.createLinearGradient(0,0,0,14);g.addColorStop(0,'#263c4466');g.addColorStop(1,'#263c4400');c.fillStyle=g;c.fillRect(0,0,(cw-.07)*P.HW,14);});
