const officeState={level:null,chutes:null,mode:'edit',elapsed:0,traces:[]};
const officeTraceSources=[],officeTraceViews=[];
const officeSelection={x:0,y:0};
// The host's accessible hatch button follows this floor corner, leaving the
// cat and its postal tickets clear. This is presentation metadata only.
const officeHatchMarker=Object.freeze({x:.96,y:.04});
const officeMedia=matchMedia('(prefers-reduced-motion: reduce)');
const officeScale=16/CivicProjection.HW;
let officeRenderer=null,officeCanvas=null,officeMounted=false,officeOutput=false,officeDensity=1,officeGeometry=false,officeBytes=0;
let officeMotion=true;
// The room manager keeps this record. View-sized scenery caches are prepared
// after mount and resized with the camera, so report their current backing.
const officeResources={get bytes(){return officeBytes+(officeRenderer?.scenery?.bytes||0);},buffers:0,scope:'architecture, exterior, backdrop, foreground, canal, board and carrier canvas backing estimate, plus ticket and live scenery view caches; excludes decoded images, other caches, live output and process peak'};
function officeMotionAllowed(){return officeMotion&&(window.PostPreferences?!document.documentElement.classList.contains('reduced'):!officeMedia.matches);}
function officeEligible(){
 if(!officeMounted||!GAME_MODE||!G_KEEP_PROGRESS||ACTIVE_ROOM.id!=='office'||lightSetName==='night'||(cpActive()&&!window.OfficeChapter?.active())||gm.custom||gm.daily||gm.practice||gm.shift||!gm.L||!officeIds.has(gm.L.id)||paperAtlasBuilding||G_GALLERY.length)return false;
 const L=gm.L,B=L.board;
 return B.w>=5&&B.w<=6&&B.h>=3&&B.h<=4&&!(L.gates&&L.gates.length)&&!(L.flaps&&L.flaps.length)&&!(L.tunnels&&L.tunnels.length);
}
function officeView(eligible){
 if(officeGeometry===eligible)return;
 officeGeometry=eligible;
 if(eligible){
  const b=officeRenderer.architecture.bounds,x=OX+gTX(0)-gTY(0),y=OY+(gTX(0)+gTY(0))/2;
  ROOM_FIT_W=(b.right-b.left)*officeScale+16;ROOM_FIT_H=(b.bottom-b.top)*officeScale+16;
  PAN_MAX_X=Math.ceil(ROOM_FIT_W/2);PAN_MAX_Y=Math.ceil(ROOM_FIT_H/2);
  // The host's room camera retains its original G_CAM inset. Board/picking
  // still use OX/OY and the authoritative native board origin.
  VIEW_CX=x+((b.left+b.right)/2-760)*officeScale-G_CAM_X;
  VIEW_CY=y+((b.top+b.bottom)/2-465)*officeScale-G_CAM_Y;
 }else if(ACTIVE_ROOM.id==='office'){
  VIEW_CX=officeSavedView.cx;VIEW_CY=officeSavedView.cy;
  ROOM_FIT_W=officeSavedView.w;ROOM_FIT_H=officeSavedView.h;PAN_MAX_X=officeSavedView.px;PAN_MAX_Y=officeSavedView.py;
 }
}
function officePrepare(){
 const demo=window.OfficeChapter?.demo,run=gm.mode!=='edit'&&gm.sim,n=demo?demo.traces.length:run?gm.sim.n:0;
 officeState.level=demo?demo.level:gm.L;officeState.chutes=demo?demo.turns:gm.chutes;officeState.mode=demo?'running':gm.mode;officeState.elapsed=demo?(CP.frame%(demo.loop*60))/60:gm.t;
 officeState.traces.length=n;
 for(let i=0;i<n;i++){
  const tr=demo?demo.traces[i]:G_TRACES[i];
  if(officeTraceSources[i]!==tr){
   officeTraceSources[i]=tr;
   // Reused facades inherit current scalar/typed-array trace fields. Only the
   // presentation origin changes; never mutate the canonical shared trace.
   officeTraceViews[i]=Object.create(tr);officeTraceViews[i].ox=officeTraceViews[i].oy=0;
  }
  officeState.traces[i]=officeTraceViews[i];
 }
 const r=officeRenderer;
 officeSelection.x=gm.cx;officeSelection.y=gm.cy;
 r.selected=!cpActive()&&gm.cursor&&gm.mode!=='running'?officeSelection:null;
 r.motion=officeMotionAllowed();r.gray=grayscale;
}
function officeDraw(){
 const r=officeRenderer,S=paperRenderScale(),w=LW*S,h=LH*S;
 if(officeCanvas.width!==w||officeCanvas.height!==h){officeCanvas.width=w;officeCanvas.height=h;}
 officeDensity=S;r.dpr=S;r.config.width=LW;r.config.height=LH;
 r.cam.scale=officeScale;
 r.cam.tx=OX+gTX(0)-gTY(0)-760*officeScale-viewX;
 r.cam.ty=OY+(gTX(0)+gTY(0))/2-465*officeScale-viewY;
 officePrepare();r.draw(officeState);officeOutput=true;
 // Native floor depth remains available to the host's accessible cursor. It
 // comes from the unchanged canonical composition, never stale paper buffers.
 paperReady=false;
}
function officeSetMotion(value){officeMotion=!!value;if(officeRenderer)officeRenderer.motion=officeMotion;dirty=true;}
function officePreference(){dirty=true;}
function officeInstall(){
 resolve=function(){
  const eligible=officeEligible();officeView(eligible);officeOutput=false;
  if(eligible){officeDraw();return;}
  return officeNative.resolve();
 };
 paperOutputCanvas=function(){return officeOutput&&officeEligible()?officeCanvas:officeNative.paperOutputCanvas();};
 paperOutputScale=function(){return officeOutput&&officeEligible()?officeDensity:officeNative.paperOutputScale();};
 update=function(){if(officeEligible()&&officeMotionAllowed()&&!document.hidden)officeRenderer.ambient+=DT;return officeNative.update();};
 api.hooks({night:()=>false});
 window.OfficePaper={active:officeEligible,motionAllowed:officeMotionAllowed,motion:officeSetMotion,hatchMarker:officeHatchMarker,
  seek(seconds){if(!Number.isFinite(seconds)||seconds<0)throw RangeError('Office time must be nonnegative');officeRenderer.ambient=seconds;dirty=true;},
  state(){return {active:officeEligible(),time:officeRenderer.ambient,motion:officeMotionAllowed(),ready:officeMounted,bakes:officeRenderer.architecture.bakes,level:gm.L.id,density:officeDensity};}};
}
return {
 async mount(){
  api.check();officeCanvas=document.createElement('canvas');officeRenderer=new CivicRenderer(officeCanvas,OfficePaperAssets,true);
  officeRenderer.cam={tx:0,ty:0,scale:officeScale};officeRenderer.guides=false;
  await officeRenderer.load();api.check();officeMounted=true;
  officeMedia.addEventListener('change',officePreference);officeInstall();officeView(officeEligible());window.OfficeChapter?.invalidate();if(window.OfficeChapter?.active())cpWorld();
  officeBytes=0;
  const count=canvas=>{if(canvas)officeBytes+=canvas.width*canvas.height*4;};
  for(const layer of officeRenderer.architecture.layers)count(layer.canvas);
  count(officeRenderer.architecture.exteriorLayer?.canvas);count(officeRenderer.backdrop?.canvas);count(officeRenderer.backdrop?.foreground?.canvas);
  officeBytes+=officeRenderer.canal?.cacheBytes||0;
  for(const canvas of officeRenderer.pieces?.carriers||[])count(canvas);
  officeBytes+=officeRenderer.tickets?.bytes||0;
  if(officeRenderer.boardCaches)for(const layer of officeRenderer.boardCaches.values())count(layer.canvas);
  dirty=true;
 },
 refresh(){api.check();officeView(officeEligible());officeOutput=false;dirty=true;},
 dispose(){officeMounted=false;officeOutput=false;officeMedia.removeEventListener('change',officePreference);officeView(false);officeRenderer=null;officeCanvas=null;officeState.traces.length=officeTraceViews.length=officeTraceSources.length=0;},
 resources(){return officeResources;}
};
